cmd:
$ErrorActionPreference='Stop'
$fixture=Join-Path ([IO.Path]::GetTempPath()) ('susi-channel-guard-'+[Guid]::NewGuid().ToString('N'))
$dev=Join-Path $fixture 'dev'
$production=Join-Path $fixture 'production'
[void][IO.Directory]::CreateDirectory($dev)
[void][IO.Directory]::CreateDirectory($production)
$record=Join-Path $production 'channel.json'
[IO.File]::WriteAllText($record,'malformed sentinel that must never be read')
$expected=(Get-FileHash -LiteralPath $record).Hash
foreach($action in 'Build','Rollback','Run','Status'){
    $reason=$null
    try { & ./scripts/susi-local.ps1 -Channel production -Root $fixture -Action $action }
    catch { $reason=$_.Exception.Message }
    if($reason -notlike 'Production requires the native release workflow.*'){throw "Production $action guard failed: $reason"}
}
if((Get-FileHash -LiteralPath $record).Hash -ne $expected -or @(Get-ChildItem -LiteralPath $production -Force).Count -ne 1){throw 'Production fixture changed'}
[IO.File]::WriteAllText((Join-Path $dev 'channel.json'),'{"channel":"dev","version":"fixture"}')
$status=& ./scripts/susi-local.ps1 -Channel dev -Root $fixture -Action Status | ConvertFrom-Json
if($status.version -ne 'fixture'){throw 'Development status regression'}
'5 channel checks passed'
& cargo test --offline --locked -p xtask --features release-tooling --bin local-release prepare_release::tests
if($LASTEXITCODE){exit $LASTEXITCODE}
& cargo test --offline --locked -p susi-harness --lib native_shortcut_and_expandable_user_path_are_idempotent
if($LASTEXITCODE){exit $LASTEXITCODE}
& cargo test --offline --locked -p susi --bin susi qualified_ordinary_channel_preserves_live_images_recovers_and_rejects_tampering
if($LASTEXITCODE){exit $LASTEXITCODE}
& cargo test --offline --locked -p susi --test installed_windows_entry
if($LASTEXITCODE){exit $LASTEXITCODE}
